const input = $input.first().json;
const body = input.body || input;

const errors = [];

if (!body.discord_user_id) {
  errors.push('Missing required parameter: discord_user_id');
}

if (!body.discord_channel_id && !body.discord_webhook_url) {
  errors.push('Missing required parameter: discord_channel_id or discord_webhook_url');
}

if (!body.label) {
  errors.push('Missing required parameter: label');
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    discord_user_id: body.discord_user_id,
    discord_channel_id: body.discord_channel_id,
    discord_webhook_url: body.discord_webhook_url || process.env.DISCORD_RECIPES_WEBHOOK_URL,
    timer_id: body.timer_id,
    recipe_id: body.recipe_id,
    recipe_title: body.recipe_title || '',
    label: body.label,
    duration_minutes: body.duration_minutes || 0,
    created_at: body.created_at,
    expired_at: new Date().toISOString()
  }
}];

