const input = $input.first().json;
const prevData = $('Validate Input').first().json;

try {
  if (input.error) {
    return [{
      json: {
        success: false,
        error: {
          code: input.error.status || 500,
          message: input.error.message || 'Discord notification failed',
          status: 'DISCORD_ERROR'
        },
        meta: { provider: 'discord' }
      }
    }];
  }

  return [{
    json: {
      success: true,
      data: {
        notification_sent: true,
        timer_id: prevData.timer_id,
        discord_user_id: prevData.discord_user_id,
        label: prevData.label,
        sent_at: new Date().toISOString()
      },
      meta: {
        provider: 'discord'
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to process notification: ' + e.message,
        status: 'PROCESS_ERROR'
      },
      meta: { provider: 'discord' }
    }
  }];
}
